-- 문서분류별 이미지 (IMEX_HIS_CD 01~04, Task ID = 마스터||분류코드)
INSERT INTO CSPD002TG (INPT_MST_SRNO, INPT_ELMT_ID, IMEX_HIS_CD, INPT_BL_GRP_NO, INPT_TASK_ID, AI_INPT_PAPS_QLT_SCRE, TRN_LOG_SRNO, LST_DB_CHG_ID, LST_DB_CHG_DTM)
SELECT M.INPT_MST_SRNO, 'ELMT' || M.INPT_MST_SRNO || C.IMEX_HIS_CD, C.IMEX_HIS_CD, M.INPT_BL_GRP_NO, TO_CHAR(M.INPT_MST_SRNO) || C.IMEX_HIS_CD, 92.0, TO_CHAR(M.INPT_MST_SRNO) || C.IMEX_HIS_CD, 'SYSTEM', '20260713120000'
  FROM CSPD001TM M
 CROSS JOIN (SELECT '01' AS IMEX_HIS_CD FROM DUAL UNION ALL SELECT '02' FROM DUAL UNION ALL SELECT '03' FROM DUAL UNION ALL SELECT '04' FROM DUAL) C
 WHERE M.INPT_MST_SRNO BETWEEN 10004 AND 10015;

